<!doctype html><html lang="id"><?php $site=site_profile(); ?><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Informasi koperasi · <?= h($site['site_name']) ?></title><link rel="icon" href="<?= base_url($site['favicon_path']) ?>"><link rel="stylesheet" href="<?= base_url('assets/vendor/tabler/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/css/app.css?v=20261105j') ?>"></head><body class="public-body"><header class="public-header"><a class="public-brand" href="<?= site_url('/') ?>"><img class="pemkab-logo" width="35" height="46" style="width:35px;height:46px;object-fit:contain;flex:none" src="<?= base_url($site['logo_path']) ?>" alt="<?= h($site['government_name']) ?>"><span><strong><?= h($site['site_name']) ?></strong><small><?= h($site['division_name']) ?></small></span></a><nav><a href="<?= site_url('/') ?>">Beranda</a><a href="<?= site_url('informasi') ?>">Informasi</a><a href="<?= site_url('aduan') ?>">Aduan</a><a class="nav-login" href="<?= site_url('login') ?>">Masuk panel ↗</a></nav></header><main class="public-info"><div class="section-index">BERITA · AGENDA · REGULASI</div><h1>Informasi koperasi <?= h($site['government_name']) ?>.</h1><p>Informasi dan kegiatan <?= h($site['division_name']) ?> yang telah diterbitkan.</p><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari informasi</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Judul atau ringkasan"></label><label><span>Kategori</span><select name="category"><option value="">Semua</option><?php foreach ($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)$category===(string)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button></form><div class="public-info-grid"><?php foreach ($rows as $r): ?><article class="info-card"><a href="<?= site_url('informasi/'.$r['slug']) ?>"><?php if ($r['image_path']): ?><img src="<?= base_url($r['image_path']) ?>" alt="Foto <?= h($r['title']) ?>" loading="lazy"><?php else: ?><div class="info-card-art">SIKOP <span>REM</span></div><?php endif; ?><div class="info-card-copy"><small><?= h($r['category_name']) ?> · <?= h(date('d M Y',strtotime($r['published_at']))) ?></small><h2><?= h($r['title']) ?></h2><p><?= h($r['summary']?:'Baca informasi selengkapnya.') ?></p><strong>Baca selengkapnya →</strong></div></a></article><?php endforeach; ?><?php if (!$rows): ?><div class="info-empty">Belum ada informasi yang sesuai pencarian.</div><?php endif; ?></div><?php $this->load->view('partials/pagination'); ?></main><footer class="public-footer"><strong><?= h($site['site_name']) ?></strong><span><?= h($site['division_name']) ?> · <?= h($site['opd_name']) ?></span><?php $this->load->view('public/profile_links'); ?></footer></body></html>
